use agentranch::{adapters::{ao_http::AoHttp,AoPort,WorkRequest},config::AoConfig};
use serde_json::{json,Value};
use std::io::{Read,Write};
#[test]
fn ao_adapter_posts_fixed_worker_request_and_checks_response(){let listener=std::net::TcpListener::bind("127.0.0.1:0").unwrap();let address=listener.local_addr().unwrap();let server=std::thread::spawn(move||{let(mut s,_)=listener.accept().unwrap();s.set_read_timeout(Some(std::time::Duration::from_secs(3))).unwrap();let mut bytes=Vec::new();let split=loop{let mut b=[0u8;1];s.read_exact(&mut b).unwrap();bytes.push(b[0]);if bytes.ends_with(b"\r\n\r\n"){break bytes.len()}};let header=String::from_utf8(bytes.clone()).unwrap();assert!(header.starts_with("POST /api/v1/sessions HTTP/1.1\r\n"));let len:usize=header.lines().find_map(|l|l.to_ascii_lowercase().strip_prefix("content-length:").map(|v|v.trim().parse().unwrap())).unwrap();let mut body=vec![0;len];s.read_exact(&mut body).unwrap();bytes.extend(&body);let request:Value=serde_json::from_slice(&bytes[split..]).unwrap();let reply=json!({"session":{"id":"actual-worker-1","kind":"worker","harness":"claude-code"}}).to_string();write!(s,"HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",reply.len(),reply).unwrap();request});let cfg=AoConfig{base_url:format!("http://{address}"),project_id:"owned-project".into(),model:"claude-opus-5-5".into()};let mut ao=AoHttp::new(cfg).unwrap();let session=ao.create(&WorkRequest{run_id:"r-1".into(),attempt:1,epoch:"e-1".into(),template:"sum-v1".into(),session:"stable-request-1".into(),project_work:None}).unwrap();assert_eq!(session,"actual-worker-1");let request=server.join().unwrap();assert_eq!(request["projectId"],"owned-project");assert_eq!(request["clientRequestId"],"stable-request-1");assert_eq!(request["kind"],"worker");assert!(request["prompt"].as_str().unwrap().contains("sum_values"));}
#[cfg(windows)]
#[test]
fn reason_named_pipe_uses_actual_ipc_and_exact_send_receipt(){use windows_sys::Win32::{System::Pipes::{CreateNamedPipeW,ConnectNamedPipe,PIPE_TYPE_BYTE,PIPE_WAIT},Storage::FileSystem::PIPE_ACCESS_DUPLEX,Foundation::{INVALID_HANDLE_VALUE,GetLastError,ERROR_PIPE_CONNECTED}};use std::os::windows::io::{FromRawHandle,RawHandle};use agentranch::adapters::reason::Reason;let endpoint=format!(r"\\.\pipe\ao-native-test-{}",uuid::Uuid::new_v4());let wide:Vec<u16>=endpoint.encode_utf16().chain(Some(0)).collect();let handle=unsafe{CreateNamedPipeW(wide.as_ptr(),PIPE_ACCESS_DUPLEX,PIPE_TYPE_BYTE|PIPE_WAIT,1,65536,65536,3000,std::ptr::null())};assert_ne!(handle,INVALID_HANDLE_VALUE);let raw=handle as usize;let server=std::thread::spawn(move||{let h=raw as windows_sys::Win32::Foundation::HANDLE;let ok=unsafe{ConnectNamedPipe(h,std::ptr::null_mut())};assert!(ok!=0||unsafe{GetLastError()}==ERROR_PIPE_CONNECTED);let mut file=unsafe{std::fs::File::from_raw_handle(h as RawHandle)};let mut frame=Vec::new();loop{let mut b=[0];file.read_exact(&mut b).unwrap();frame.push(b[0]);if b[0]==b'\n'{break}}let request:Value=serde_json::from_slice(&frame).unwrap();let reply=json!({"id":request["id"],"ok":true,"result":{"recipients":[{"address":"node-B/runner","state":"queued"}],"ids":["owned-receipt-1"]}});writeln!(file,"{reply}").unwrap();request});let reason=Reason::new(endpoint).unwrap();let result=reason.send("A","node-B/runner","m-1","{}").unwrap();assert_eq!(result["ids"][0],"owned-receipt-1");let request=server.join().unwrap();assert_eq!(request["op"],"send");assert_eq!(request["wake"],false);assert_eq!(request["idempotency_key"],"m-1");}
